entries[53385] = { ["name"] = "Göttlicher Sturm", ["text"] = "3 Heilige Kraft\nSofort\nEntfesselt einen Wirbel göttlicher Energie, der allen Gegnern in der Nähe [ Brennender Kreuzzug : [(128.05% der Angriffskraft) * 1.05] Strahlenschaden / (128.05% der Angriffskraft) Heiligschaden] zufügt.\n\nFügt Zielen über 5 Ziele hinaus verringerten Schaden zu." }
entries[53389] = { ["name"] = "GPS (Großdrachen-Positionierungs-System)", ["text"] = "Sofort\nBefragt Euren Drachen über den nächsten Schritt in der Wiedereroberung des Oculus." }
entries[53390] = { ["name"] = "Flutwellen", ["text"] = "Sofort\nDer Einsatz von 'Springflut' gewährt 2 Stapel von 'Flutwellen'. 'Flutwellen' verringert die Zauberzeit Eurer nächsten 'Welle der Heilung' oder 'Kettenheilung' um 20% oder erhöht die Chance auf einen kritischen Effekt mit Eurer nächsten 'Heilende Woge' um 30%." }
entries[53392] = { ["name"] = "Geheime Stärke der Wildherzen mixen", ["text"] = "Wirken in 2 sek.\nReagenzien:\nDonnerbräus Starkbier , Wolvarbeeren\nMixt die Wolvarbeeren mit Donnerbräus Starkbier, um das geheime Gebräu der Wildherzen zu erhalten." }
