entries[53480] = { ["name"] = "Brüllen der Aufopferung", ["text"] = "40 Meter Reichweite\nSofort 1 min Abklingzeit\nTierherrschaft, Überleben\nBefiehlt Eurem Tier, ein verbündetes Ziel davor zu schützen, kritische Treffer zu erleiden. Gegen das Ziel geführte Angriffe können nicht kritisch treffen, jedoch werden 10% des gesamten erlittenen Schadens auch von Eurem Tier erlitten. Hält 12 Sek. lang an.\n\nTreffsicherheit\nBefiehlt Eurem Tier, ein verbündetes Ziel davor zu schützen, kritische Treffer zu erleiden. Gegen das Ziel geführte Angriffe können nicht kritisch treffen. Hält 12 Sek. lang an.\n\nWährend 'Brüllen der Aufopferung' aktiv ist, kann Euer Spähadler kein 'Mal des Spähers' anwenden." }
entries[53482] = { ["name"] = "Blut des Rhinozeros", ["text"] = "Erhöht die erhaltenen Heileffekte Eures Begleiters um 40%, verringert den erlittenen körperlichen Schaden um 15% und verringert seine Chance, kritische Nahkampftreffer zu erleiden, um 6%." }
