entries[53490] = { ["name"] = "Stur wie ein Ochse", ["text"] = "Sofort 3 min Abklingzeit\nEntfernt alle bewegungseinschränkenden Effekte sowie Effekte, die zum Kontrollverlust über Euer Tier führen. Verringert zudem 12 Sek. lang den erlittenen Schaden Eures Tiers um 20%." }
