entries[53496] = { ["name"] = "Hervorschießende Flammen", ["text"] = "Wirken in 0.5 sek.\nAus den Händen des Zaubernden treten Feuerpfeile aus und fügen Gegnern in der Nähe Feuerschaden zu." }
