entries[53534] = { ["name"] = "Eisketten", ["text"] = "20 Meter Reichweite\nSofort\nFriert das Ziel 3 Sek. lang fest. Während dieser Zeit gilt das Ziel als eingefroren. Nach dem Ausbruch aus den Ketten erhält das Ziel pro Sekunde 10% seiner Bewegungsgeschwindigkeit zurück." }
entries[53536] = { ["name"] = "Heulende Böe", ["text"] = "20 Meter Reichweite\nSofort\nWeht dem Ziel eine eisige Böe entgegen, die allen Zielen innerhalb von 10 Metern 3 Frostschaden zufügt. Gefrorene Ziele erleiden dreifachen Schaden." }
