entries[53549] = { ["name"] = "Eisige Berührung", ["text"] = "20 Meter Reichweite\nSofort\nVerursacht 1 bis 1 Frostschaden (modifiziert durch Angriffskraft) und verringert bis Abbruch lang das Nahkampfangriffs-, Distanzangriffs- und Zaubertempo des Ziels um 1%." }
entries[53550] = { ["name"] = "Gedankenfrost", ["text"] = "Nahkampfreichweite\nSofort\nDie Gedanken des Ziels werden von einer Kälte geschlagen, die 1 Frostschaden verursacht (modifiziert durch Angriffskraft). Das Wirken von Zaubern wird unterbrochen sowie 4 Sek. lang verhindert, dass Zauber dieser Art gewirkt werden können." }
entries[53563] = { ["name"] = "Flamme des Glaubens", ["text"] = "0.5% von Grundmana 60 Meter Reichweite\nSofort\nHüllt einen einzelnen Verbündeten in heilige Energie, durch die Eure auf andere Gruppen- oder Schlachtzugsmitglieder gewirkte direkte Heilung dieses Ziel zusätzlich in Höhe von 20% des geheilten Werts heilt." }
entries[53570] = { ["name"] = "Zehrende Kälte", ["text"] = "10 Meter Reichweite\nSofort\nEntfesselt alle verfügbare Runenmacht, um der Erde unter dem Todesritter jegliche Wärme zu entziehen. Feinde innerhalb von 10 Metern werden in Eis eingeschlossen, das für 1 Sek. pro 5 Runenmacht jegliche ihrer Aktionen verhindert. Feinde zählen als eingefroren, jeglicher verursachte Schaden unterbricht den Effekt." }
entries[53576] = { ["name"] = "Lichtinfusion", ["text"] = "Eure Einsätze von 'Heiliger Schock' haben eine Chance von 10%, Euren nächsten Zauber zu ermächtigen:\n\nLichtblitz : Heilung um 150% erhöht und wird zum Spontanzauber.\nHeiliges Licht : Heilung um 30% erhöht und Zauberzeit um 30% verringert.\nRichturteil : 'Großes Richturteil' verhindert 100% mehr Schaden und erzeugt 1 zusätzliche Heilige Kraft." }
entries[53595] = { ["name"] = "Hammer der Rechtschaffenen", ["text"] = "0.32% von Grundmana Nahkampfreichweite\nSofort 5 sek. Wiederaufladung\n2 Aufladungen\nLässt einen Hammer auf das aktuelle Ziel niedergehen, der ihm (97.5% der Angriffskraft)% körperlichen Schaden zufügt. [ Weihe : 'Hammer der Rechtschaffenen' ruft zusätzlich eine Lichtwelle hervor, die allen anderen Zielen innerhalb von 8 Metern (13.56% der Angriffskraft)% Heiligschaden zufügt ] [ Während Ihr Euch im Effektbereich Eurer 'Weihe' aufhaltet, löst 'Hammer der Rechtschaffenen' zudem eine Lichtwelle aus, die allen anderen Zielen innerhalb von 8 Metern (13.56% der Angriffskraft)% Heiligschaden zufügt ]\nErzeugt 1 Heilige Kraft." }
