entries[53635] = { ["name"] = "Umarmung des Todes", ["text"] = "Sofort\nSchlägt alle Gegner in der Nähe, verursacht dabei 98 Schaden und heilt alle Verbündeten in der Nähe um 71." }
entries[53636] = { ["name"] = "Antimagisches Feld", ["text"] = "10 Meter Reichweite\nKanalisiert (Wirken in 0 sek.)\nPlatziert ein großes, ortsgebundenes, antimagisches Feld, das den erlittenen Zauberschaden aller darin befindlichen Gruppenmitglieder um 49% verringert. Das antimagische Feld hält entweder 6 Sek. lang an oder bis es 0 Zauberschaden absorbiert hat." }
