entries[53638] = { ["name"] = "Heiliger Zorn", ["text"] = "35 Meter Reichweite\nSofort\nSchleudert Blitze heiliger Macht in alle Richtungen. Fügt allen Zielen innerhalb von 0 Metern (100% der Zaubermacht) Heiligschaden zu, mit jedem Sprung verdoppelt sich der Schaden." }
entries[53639] = { ["name"] = "Todesstoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort an, verursacht 600% Waffenschaden und eine Krankheit, die im Verlauf von 21 Sek. 350 Schaden zufügt. Alle auf das Ziel wirkenden, Heilung über Zeit verursachenden Effekte werden verderbt und erhöhen den verursachten Schaden der Krankheit dramatisch. Der Heileffekt wird dabei entfernt." }
entries[53640] = { ["name"] = "Unheilige Verseuchung", ["text"] = "Sofort\nEin widerwärtiger Schwarm unheiliger Insekten umgibt den Zaubernden in einem Radius von 10 Metern. Alle Gegner, die sich im Schwarm aufhalten, erleiden pro Sek. 0 Schaden und werden mit einer Krankheit angesteckt, die bis zu 3-mal stapelbar ist. Hält pro 10 Runenmacht 1 Sek. lang an. Das Erzeugen von Runenmacht, während der Effekt andauert, kann ihn verlängern." }
entries[53641] = { ["name"] = "Unheilige Verseuchung", ["text"] = "Sofort\nEin widerwärtiger Schwarm unheiliger Insekten umgibt den Zaubernden in einem Radius von 10 Metern. Alle Gegner, die sich im Schwarm aufhalten, erleiden pro Sek. 200 Schaden und werden mit einer Krankheit angesteckt, die bis zu 3-mal stapelbar ist. Hält pro 10 Runenmacht 1 Sek. lang an." }
entries[53642] = { ["name"] = "Die Macht von Mograine", ["text"] = "150 Meter Reichweite\nSofort\nVon der Macht des Hochlords Darion Mograine erfüllt. Euer Schaden, Eure Gesundheit und Eure Gesundheitsregeneration sind stark erhöht. Ihr seid eine unaufhaltbare Macht der Dunkelheit!" }
